sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        //MSSCUSTODY-3176 : Change in High Value Trade field calculation 
        // Setting the High Value trade based on the high value property.
        var highValueTrade = gs.getProperty('x_hsb11_mss_c_proc.mss_custody_value_for_high_value_trade');
        var settlementAmount = current.settlement_amount_in_usd;
        var nominalAmount = current.nominal_settlement_amount_in_usd;

        if ((settlementAmount >= highValueTrade) || (nominalAmount >= highValueTrade))
            current.high_value_trade = 'Yes';
        else
            current.high_value_trade = 'No';
    } catch (error) {
        gs.info(error.message);
        current.setAbortAction(true);
    }
})(current, previous);
